lemma imo2019_p1 (f : ℤ → ℤ) :
    (∀ a b, f (2 * a) + 2 * (f b) = f (f (a + b))) ↔ f ∈ solution_set  := by
  constructor; swap
  · intro hf a b; cases' hf with hf1 hf2; simp [hf1, hf2]
  intro hf;
  let g : ℤ → ℤ := fun z => f z - f 0;
  have hg : ∀ z, g z = f z - f 0 := fun z => rfl;
  have : ∀ x y, g (x + y) = g x + g y := by
    intro x y; simp [hg];
    obtain ⟨d, hd⟩ := additive_to_int_linear g this;
    have hz : ∀ z, f z = d * z + f 0 := by
      intro z; rw [← hd z, hg, sub_add_cancel];
    cases' em (d = 0) with hd hd; simp [hf₀] at ⊢ hd ⊢; linarith
